   214→    /* Populate recovered_cells_fr with available cells at the right places */
   215→    for (size_t i = 0; i < num_cells; i++) {
   216→        size_t index = cell_indices[i] * FIELD_ELEMENTS_PER_CELL;
   217→        for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   218→            /* Convert the untrusted input bytes to a field element */
